import base64
import json
import urllib.request
import urllib.error

node_ids = [
    (1, "RmVsbG93UmVwbzox"),
    (1000, "RmVsbG93UmVwbzoxMDAw"),
    (1000000, "RmVsbG93UmVwbzoxMDAwMDAw"),
    (1000000000, "RmVsbG93UmVwbzoxMDAwMDAwMDAw"),
]

url = "https://api.github.com/graphql"

query = """
query($id: ID!) {
  repository(id: $id) {
    nameWithOwner
    owner {
      login
    }
    stargazers {
      totalCount
    }
    forks {
      totalCount
    }
    createdAt
    description
    primaryLanguage {
      name
    }
    url
  }
}
"""

result = {}

for repo_id, nid in node_ids:
    payload = json.dumps({"query": query, "variables": {"id": nid}}).encode()
    req = urllib.request.Request(url, data=payload, headers={"Content-Type": "application/json"})
    try:
        resp = urllib.request.urlopen(req, timeout=30)
        data = json.loads(resp.read().decode())
        repo = data.get("data", {}).get("repository", {})
        if repo and repo.get("url"):
            primary_lang = repo.get("primaryLanguage")
            result[str(repo_id)] = {
                "repo_name": repo["nameWithOwner"],
                "owner": repo["owner"]["login"],
                "star_count": repo["stargazers"]["totalCount"],
                "fork_count": repo["forks"]["totalCount"],
                "creation_time": repo["createdAt"],
                "description": repo.get("description") or "",
                "language": primary_lang["name"] if primary_lang else "",
                "repo_url": repo["url"]
            }
            print(f"Repo ID {repo_id}: OK - {repo['nameWithOwner']}")
        else:
            print(f"Repo ID {repo_id}: not found or inaccessible")
    except Exception as e:
        print(f"Repo ID {repo_id}: error - {e}")

with open("/app/github_info.json", "w") as f:
    json.dump(result, f, indent=4)

print("\nSaved to github_info.json")
PYEOF
